#include <algorithm>
#include <cctype>
#include <cstdint>
#include <string>
#include <vector>

struct Candidate
{
    std::string file;
    bool loads{ true };
    bool hasExport{ true };
    uint32_t tableSize{ 0 };
    uint32_t apiVersion{ 0 };
    std::string name;
    bool startOk{ true };
};

struct ScanResult { std::vector<std::string> kept; std::vector<std::string> log; };

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

ScanResult scanPlugins(const std::vector<Candidate>& files, uint32_t hostApiVersion, uint32_t requiredTableSize)
{
    std::vector<Candidate> sorted{ files };
    std::sort(sorted.begin(), sorted.end(), [](const Candidate& a, const Candidate& b) { return lower(a.file) < lower(b.file); });
    ScanResult r;
    for (const Candidate& c : sorted)
    {
        const std::string l{ lower(c.file) };
        if (l.size() < 4 || l.compare(l.size() - 4, 4, ".dll") != 0) { r.log.push_back(c.file + ": not a DLL"); continue; }
        if (!c.loads) { r.log.push_back(c.file + ": could not load"); continue; }
        if (!c.hasExport) { r.log.push_back(c.file + ": not a plugin"); continue; }
        if (c.tableSize < requiredTableSize || c.apiVersion != hostApiVersion)
        {
            r.log.push_back(c.file + ": built for API version " + std::to_string(c.apiVersion) + ", need " + std::to_string(hostApiVersion));
            continue;
        }
        if (std::find(r.kept.begin(), r.kept.end(), c.name) != r.kept.end()) { r.log.push_back(c.file + ": duplicate plugin " + c.name); continue; }
        if (!c.startOk) { r.log.push_back(c.file + ": start failed"); continue; }
        r.kept.push_back(c.name);
        r.log.push_back(c.file + ": loaded " + c.name);
    }
    return r;
}

