Candidate good(const char* file, const char* name) { Candidate c; c.file = file; c.name = name; c.tableSize = 48; c.apiVersion = 1; return c; }
TEST("two good plugins, sorted") {
    const auto r = scanPlugins({ good("rain.dll", "Rain"), good("Fog.dll", "Fog") }, 1, 48);
    CHECK_EQ(r.kept, (std::vector<std::string>{ "Fog", "Rain" }));
    CHECK_EQ(r.log, (std::vector<std::string>{ "Fog.dll: loaded Fog", "rain.dll: loaded Rain" }));
}
TEST("each kind of rejection") {
    Candidate txt = good("readme.txt", "x");
    Candidate broken = good("broken.dll", "x"); broken.loads = false;
    Candidate other = good("other.dll", "x"); other.hasExport = false;
    Candidate old = good("old.dll", "Old"); old.apiVersion = 0;
    Candidate small = good("small.dll", "Small"); small.tableSize = 24;
    Candidate failing = good("zz.dll", "ZZ"); failing.startOk = false;
    const auto r = scanPlugins({ txt, broken, other, old, small, failing }, 1, 48);
    CHECK(r.kept.empty());
    CHECK_EQ(r.log, (std::vector<std::string>{ "broken.dll: could not load", "old.dll: built for API version 0, need 1", "other.dll: not a plugin", "readme.txt: not a DLL", "small.dll: built for API version 1, need 1", "zz.dll: start failed" }));
}
TEST("duplicate names") { const auto r = scanPlugins({ good("a.dll", "Fog"), good("b.DLL", "Fog") }, 1, 48); CHECK_EQ(r.kept, (std::vector<std::string>{ "Fog" })); CHECK_EQ(r.log.back(), std::string("b.DLL: duplicate plugin Fog")); }
TEST("empty folder") { const auto r = scanPlugins({}, 1, 48); CHECK(r.kept.empty()); CHECK(r.log.empty()); }

